// Some portions generated by Claude
'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const vm = require('node:vm');
const { workbenchScriptPath } = require('./workbench-scripts.js');

/** The compiled queryTabs.js in a bare sandbox: the state logic needs no DOM. */
function loadQueryTabs() {
    const context = vm.createContext({ workbench: {}, console, Intl, Date, Math, JSON });
    vm.runInContext(fs.readFileSync(workbenchScriptPath('queryTabs.js'), 'utf8'), context, { filename: 'queryTabs.js' });
    return context.workbench.queryTabs;
}

function mapStorage(initial = {}) {
    const map = new Map(Object.entries(initial));
    return {
        map,
        getItem: (key) => (map.has(key) ? map.get(key) : null),
        setItem: (key, value) => { map.set(key, String(value)); },
        removeItem: (key) => { map.delete(key); }
    };
}

test('deriveTitle skips prefixes, comments and blank lines, collapses whitespace and cuts long lines', () => {
    const tabs = loadQueryTabs();
    assert.equal(tabs.deriveTitle('PREFIX ex: <http://e/>\n\nSELECT ?s WHERE { ?s a ex:T }'), 'SELECT ?s WHERE { ?s a ex:T }');
    assert.equal(tabs.deriveTitle('# count the types\nBASE <http://x/>\n  SELECT   ?type\t(COUNT(*) AS ?n)'),
        'SELECT ?type (COUNT(*) AS ?n)');
    assert.equal(tabs.deriveTitle('prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>'), 'Untitled query');
    assert.equal(tabs.deriveTitle(''), 'Untitled query');
    assert.equal(tabs.deriveTitle(null), 'Untitled query');
    const long = 'SELECT ?a ?b ?c ?d ?e ?f ?g WHERE { ?a ?b ?c . ?d ?e ?f . ?g ?a ?b }';
    const title = tabs.deriveTitle(long);
    assert.equal(title.length, 40);
    assert.ok(title.endsWith('…'));
    assert.equal(title.slice(0, 39), long.slice(0, 39));
});

test('titleOf prefers the explicit name and isDerivedTitle tells the two apart', () => {
    const tabs = loadQueryTabs();
    const named = tabs.newTab('SELECT * WHERE { ?s ?p ?o }', { title: 'Everything', saved: true });
    const unnamed = tabs.newTab('SELECT * WHERE { ?s ?p ?o }');
    assert.equal(tabs.titleOf(named), 'Everything');
    assert.equal(tabs.isDerivedTitle(named), false);
    assert.equal(tabs.titleOf(unnamed), 'SELECT * WHERE { ?s ?p ?o }');
    assert.equal(tabs.isDerivedTitle(unnamed), true);
    assert.equal(named.saved, true);
    assert.equal(unnamed.saved, false);
    assert.equal(unnamed.queryLn, 'SPARQL');
    assert.notEqual(named.id, unnamed.id);
});

test('parseState rejects garbage and other versions, repairs a bad active id and drops malformed tabs', () => {
    const tabs = loadQueryTabs();
    assert.equal(tabs.parseState(''), null);
    assert.equal(tabs.parseState('not json'), null);
    assert.equal(tabs.parseState('{"version":2,"tabs":[]}'), null);
    assert.equal(tabs.parseState('{"version":1,"tabs":[]}'), null);
    assert.equal(tabs.parseState('{"version":1,"tabs":[{"nope":true}]}'), null);
    const state = tabs.parseState(JSON.stringify({
        version: 1,
        activeId: 'missing',
        tabs: [
            { id: 'a', query: 'ASK {}', lastRun: { status: 'done', rowCount: 1, total: 1, at: 5 }, extra: 'ignored' },
            { id: 'a', query: 'duplicate id gets a new one' },
            { query: 'no id', title: '', saved: 'yes', lastRun: { status: 'bogus' } },
            { id: 'b' }
        ]
    }));
    assert.equal(state.tabs.length, 3);
    assert.equal(state.activeId, 'a');
    assert.equal(state.tabs[0].lastRun.rowCount, 1);
    assert.equal(state.tabs[0].lastRun.elapsedMs, null);
    assert.notEqual(state.tabs[1].id, 'a');
    assert.equal(state.tabs[2].title, null);
    assert.equal(state.tabs[2].saved, true);
    assert.equal(state.tabs[2].lastRun, null);
    assert.ok(state.tabs[2].id);
    const roundTrip = tabs.parseState(tabs.serializeState(state));
    assert.deepEqual(roundTrip, state);
});

test('open appends and activates up to the limit; close picks the right neighbour then the left; the last close leaves an empty tab', () => {
    const tabs = loadQueryTabs();
    let state = tabs.emptyState();
    const first = state.tabs[0];
    const second = tabs.newTab('SELECT 2 {}');
    const third = tabs.newTab('SELECT 3 {}');
    state = tabs.open(tabs.open(state, second), third);
    assert.deepEqual(Array.from(state.tabs, tab => tab.id), [first.id, second.id, third.id]);
    assert.equal(state.activeId, third.id);

    state = tabs.activate(state, second.id);
    state = tabs.close(state, second.id);
    assert.equal(state.activeId, third.id, 'closing the active tab shows the one to its right');
    state = tabs.close(state, third.id);
    assert.equal(state.activeId, first.id, 'with nothing to the right the left neighbour is shown');
    const untouched = tabs.close(state, 'unknown');
    assert.equal(untouched, state);
    state = tabs.close(state, first.id);
    assert.equal(state.tabs.length, 1);
    assert.equal(state.tabs[0].query, '');
    assert.notEqual(state.tabs[0].id, first.id);

    let full = tabs.emptyState();
    for (let i = 1; i < tabs.MAX_TABS; i++) {
        full = tabs.open(full, tabs.newTab('SELECT ' + i + ' {}'));
    }
    assert.equal(full.tabs.length, tabs.MAX_TABS);
    const beyond = tabs.open(full, tabs.newTab('one too many'));
    assert.equal(beyond, full);
});

test('closing a background tab keeps the active one; activate ignores unknown ids', () => {
    const tabs = loadQueryTabs();
    let state = tabs.emptyState();
    const active = state.tabs[0];
    const other = tabs.newTab('SELECT 2 {}');
    state = tabs.activate(tabs.open(state, other), active.id);
    state = tabs.close(state, other.id);
    assert.equal(state.activeId, active.id);
    assert.equal(state.tabs.length, 1);
    assert.equal(tabs.activate(state, 'nope'), state);
    assert.equal(tabs.activate(state, active.id), state);
});

test('setQuery marks the tab dirty, recordRun clears it, update patches fields and findByQuery ignores whitespace', () => {
    const tabs = loadQueryTabs();
    let state = tabs.emptyState();
    const id = state.activeId;
    assert.equal(tabs.setQuery(state, id, ''), state, 'the same text is no change');
    state = tabs.setQuery(state, id, 'SELECT * WHERE { ?s ?p ?o }');
    assert.equal(tabs.activeTab(state).dirty, true);
    state = tabs.recordRun(state, id, { status: 'done', rowCount: 17, total: 17, elapsedMs: 109, at: 1 });
    assert.equal(tabs.activeTab(state).dirty, false);
    assert.equal(tabs.activeTab(state).lastRun.total, 17);
    state = tabs.update(state, id, { title: 'Types', saved: true });
    assert.equal(tabs.titleOf(tabs.activeTab(state)), 'Types');
    assert.equal(tabs.activeTab(state).saved, true);
    assert.equal(tabs.activeTab(state).lastRun.rowCount, 17, 'update keeps what the patch leaves out');
    assert.equal(tabs.findByQuery(state, '  SELECT * WHERE { ?s ?p ?o }\n').id, id);
    assert.equal(tabs.findByQuery(state, 'ASK {}'), null);
    assert.equal(tabs.update(state, 'nope', { title: 'x' }), state);
});

test('the store reads, persists and notifies; a throwing storage keeps the state in memory', () => {
    const tabs = loadQueryTabs();
    const key = tabs.storageKey('server-1', 'lmdb');
    assert.equal(key, 'rdf4j.workbench.query.tabs.v1:server-1:lmdb');
    const storage = mapStorage({ [key]: 'garbage' });
    const store = tabs.createStore(storage, key);
    assert.equal(store.get().tabs.length, 1, 'bad JSON falls back to one empty tab');
    const seen = [];
    const unsubscribe = store.subscribe(state => seen.push(state));
    const next = tabs.setQuery(store.get(), store.get().activeId, 'ASK {}');
    store.set(next);
    store.set(next);
    assert.equal(seen.length, 1, 'setting the same state again notifies nobody');
    assert.deepEqual(tabs.parseState(storage.getItem(key)), next);
    unsubscribe();
    store.set(tabs.open(next, tabs.newTab('SELECT 2 {}')));
    assert.equal(seen.length, 1);

    const reopened = tabs.createStore(storage, key);
    assert.equal(reopened.get().tabs.length, 2);
    assert.equal(reopened.get().tabs[0].query, 'ASK {}');

    const broken = {
        getItem() { throw new Error('denied'); },
        setItem() { throw new Error('denied'); }
    };
    const memory = tabs.createStore(broken, key);
    memory.set(tabs.setQuery(memory.get(), memory.get().activeId, 'SELECT 1 {}'));
    assert.equal(memory.get().tabs[0].query, 'SELECT 1 {}');
    const none = tabs.createStore(null, key, tabs.open(tabs.emptyState(), tabs.newTab('seed')));
    assert.equal(none.get().tabs.length, 2);
});
